def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)

    hsep = [r for r in range(h)
            if len(set(grid[r])) == 1 and grid[r][0] != bg]
    vsep = [c for c in range(w)
            if all(grid[r][c] == grid[0][c] for r in range(h))
            and grid[0][c] != bg]

    def spans(n, separators):
        bounds = [-1] + separators + [n]
        return [(a + 1, b) for a, b in zip(bounds, bounds[1:])]

    rows = spans(h, hsep)
    cols = spans(w, vsep)

    # Select the section containing the most non-background pattern cells.
    best = max(
        ((a, b, c, d) for a, b in rows for c, d in cols),
        key=lambda q: sum(grid[r][c] != bg
                         for r in range(q[0], q[1])
                         for c in range(q[2], q[3]))
    )
    a, b, c, d = best
    sh, sw = b - a, d - c

    out = [row[:] for row in grid]
    for ra, rb in rows:
        for ca, cb in cols:
            for r in range(ra, rb):
                for col in range(ca, cb):
                    out[r][col] = grid[a + (r - ra) % sh][c + (col - ca) % sw]
    return out
